/**
 * Email transformation function for ImportSet field mapping
 * @param {any} source - The source record data
 * @returns {string} - Transformed email value
 */
export function emailTransform(source) {
    // Transform email to lowercase and trim whitespace
    return source.email_address ? source.email_address.toString().toLowerCase().trim() : ''
}

/**
 * Phone transformation function for ImportSet field mapping
 * @param {any} source - The source record data
 * @returns {string} - Transformed phone value
 */
export function phoneTransform(source) {
    // Format phone number by removing non-digits and adding standard formatting
    const phone = source.phone_number ? source.phone_number.toString() : ''
    const digits = phone.replace(/\D/g, '')

    if (digits.length === 10) {
        return `(${digits.slice(0, 3)}) ${digits.slice(3, 6)}-${digits.slice(6)}`
    }
    return phone // Return original if not 10 digits
}
